from __future__ import annotations

from .board import Position, START_FEN

_FILES = "abcdefgh"


def square_from_name(name):
    """'e4' -> 0x88 square index."""
    return _FILES.index(name[0]) + 16 * (int(name[1]) - 1)


def name_from_square(square):
    """0x88 square index -> 'e4'."""
    return _FILES[square & 7] + str((square >> 4) + 1)


def parse_fen(fen=START_FEN):
    """Parse a FEN string into a Position.

    Only the four stateful fields are required; halfmove/fullmove counters are
    accepted but ignored (irrelevant for perft).
    """
    parts = fen.split()
    if len(parts) < 4:
        raise ValueError(f"FEN needs at least 4 fields: {fen!r}")

    rows = parts[0].split("/")
    if len(rows) != 8:
        raise ValueError(f"FEN must have 8 ranks: {parts[0]!r}")

    board = [None] * 128
    for i, row in enumerate(rows):
        rank = 7 - i
        file = 0
        for ch in row:
            if ch.isdigit():
                file += int(ch)
            elif ch in "pnbrqkPNBRQK":
                if file > 7:
                    raise ValueError(f"Rank overflow in {row!r}")
                board[rank * 16 + file] = ch
                file += 1
            else:
                raise ValueError(f"Bad FEN piece char {ch!r} in {row!r}")
        if file != 8:
            raise ValueError(f"Rank {rank + 1} has {file} files: {row!r}")

    turn = parts[1]
    if turn not in ("w", "b"):
        raise ValueError(f"Bad side to move: {parts[1]!r}")

    castling = "" if parts[2] == "-" else parts[2]
    for c in castling:
        if c not in "KQkq":
            raise ValueError(f"Bad castling field: {parts[2]!r}")

    ep = None if parts[3] == "-" else square_from_name(parts[3])

    return Position(board, turn, castling, ep)


def to_fen(pos):
    """Serialize a Position back to FEN (counters reported as 0 1)."""
    rows = []
    for rank in range(7, -1, -1):
        row, empty = "", 0
        for file in range(8):
            piece = pos.board[rank * 16 + file]
            if piece is None:
                empty += 1
            else:
                if empty:
                    row += str(empty)
                    empty = 0
                row += piece
        if empty:
            row += str(empty)
        rows.append(row)

    castling = pos.castling or "-"
    ep = name_from_square(pos.ep) if pos.ep is not None else "-"
    return f"{'/'.join(rows)} {pos.turn} {castling} {ep} 0 1"
