from __future__ import annotations

from .board import (
    A1,
    A8,
    BISHOP_DIRS,
    E1,
    E8,
    H1,
    H8,
    KING_DELTAS,
    KNIGHT_DELTAS,
    ROOK_DIRS,
    ALL_SQUARES,
    make_move,
)

# Move is a tuple: (from_sq, to_sq, promotion_char_or_None).
# Promotion chars are always uppercase ('Q', 'R', 'B', 'N').


def is_attacked(board, square, by_white):
    """True if `square` is attacked by the side given by `by_white`."""
    if by_white:
        for d in (-15, -17):  # white pawn attacks upward, so it sits below
            t = square + d
            if not (t & 0x88) and board[t] == "P":
                return True
        knight, king, diag, orth = "N", "K", ("B", "Q"), ("R", "Q")
    else:
        for d in (15, 17):
            t = square + d
            if not (t & 0x88) and board[t] == "p":
                return True
        knight, king, diag, orth = "n", "k", ("b", "q"), ("r", "q")

    for d in KNIGHT_DELTAS:
        t = square + d
        if not (t & 0x88) and board[t] == knight:
            return True
    for d in KING_DELTAS:
        t = square + d
        if not (t & 0x88) and board[t] == king:
            return True

    for dirs, sliders in ((BISHOP_DIRS, diag), (ROOK_DIRS, orth)):
        for d in dirs:
            t = square + d
            while not (t & 0x88):
                p = board[t]
                if p is not None:
                    if p in sliders:
                        return True
                    break
                t += d
    return False


def _castling_moves(pos):
    """Castling moves for the side to move (transit-square checks included)."""
    board = pos.board
    moves = []
    white = pos.turn == "w"

    if white:
        k_sq, rook_k, rook_q = E1, H1, A1
        enemy_is_white = False
    else:
        k_sq, rook_k, rook_q = E8, H8, A8
        enemy_is_white = True

    rights_k = "K" if white else "k"
    rights_q = "Q" if white else "q"
    king = "K" if white else "k"

    if board[k_sq] != king:
        return moves

    # Kingside: two empties between rook and king, king path not attacked.
    if (
        rights_k in pos.castling
        and board[rook_k] == ("R" if white else "r")
        and board[k_sq + 1] is None
        and board[k_sq + 2] is None
        and not is_attacked(board, k_sq, enemy_is_white)
        and not is_attacked(board, k_sq + 1, enemy_is_white)
        and not is_attacked(board, k_sq + 2, enemy_is_white)
    ):
        moves.append((k_sq, k_sq + 2, None))

    # Queenside: three empties, only king's path checked for attacks.
    if (
        rights_q in pos.castling
        and board[rook_q] == ("R" if white else "r")
        and board[k_sq - 1] is None
        and board[k_sq - 2] is None
        and board[k_sq - 3] is None
        and not is_attacked(board, k_sq, enemy_is_white)
        and not is_attacked(board, k_sq - 1, enemy_is_white)
        and not is_attacked(board, k_sq - 2, enemy_is_white)
    ):
        moves.append((k_sq, k_sq - 2, None))

    return moves


def pseudo_moves(pos):
    """All pseudo-legal moves for the side to move."""
    board = pos.board
    white = pos.turn == "w"
    own = str.isupper if white else str.islower
    moves = []

    for s in ALL_SQUARES:
        piece = board[s]
        if piece is None or not own(piece):
            continue
        pt = piece.upper()

        if pt == "P":
            fwd = 16 if white else -16
            start_rank = 1 if white else 6
            promo_rank = 6 if white else 1

            one = s + fwd
            if not (one & 0x88) and board[one] is None:
                if s >> 4 == promo_rank:
                    for pr in "QRBN":
                        moves.append((s, one, pr))
                else:
                    moves.append((s, one, None))
                    two = s + 2 * fwd
                    if s >> 4 == start_rank and board[two] is None:
                        moves.append((s, two, None))

            for d in (fwd - 1, fwd + 1):
                t = s + d
                if t & 0x88:
                    continue
                target = board[t]
                if target is not None and own(target) is False:
                    if s >> 4 == promo_rank:
                        for pr in "QRBN":
                            moves.append((s, t, pr))
                    else:
                        moves.append((s, t, None))
                elif target is None and t == pos.ep:
                    moves.append((s, t, None))

        elif pt == "N":
            for d in KNIGHT_DELTAS:
                t = s + d
                if not (t & 0x88):
                    target = board[t]
                    if target is None or not own(target):
                        moves.append((s, t, None))

        elif pt == "K":
            for d in KING_DELTAS:
                t = s + d
                if not (t & 0x88):
                    target = board[t]
                    if target is None or not own(target):
                        moves.append((s, t, None))

        else:  # sliders: B, R, Q
            dirs = (
                BISHOP_DIRS if pt == "B" else ROOK_DIRS if pt == "R" else KING_DELTAS
            )
            for d in dirs:
                t = s + d
                while not (t & 0x88):
                    target = board[t]
                    if target is None:
                        moves.append((s, t, None))
                    else:
                        if not own(target):
                            moves.append((s, t, None))
                        break
                    t += d

    moves.extend(_castling_moves(pos))
    return moves


def legal_moves(pos):
    """Pseudo-legal moves filtered so our own king is never left in check."""
    us_white = pos.turn == "w"
    result = []
    for mv in pseudo_moves(pos):
        nxt = make_move(pos, mv)
        if not is_attacked(nxt.board, nxt.king_square(us_white), not us_white):
            result.append(mv)
    return result


def move_to_uci(move):
    from .fen import name_from_square

    frm, to, promo = move
    return name_from_square(frm) + name_from_square(to) + (promo.lower() if promo else "")
